payload.query:
    query StudyingInfo($studentId: String) {
      studyingInfo(studentId: $studentId) {
        ...studyingInfoFields
      }
    }

fragment studyingInfoFields on StudyingInfo {
  id
  classId
  days
  timePerDay
  subjects {
    id
    name
  }
  adaptiveComplexity
  isActive
}

